<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {roles,manager,auditor,reviewer,canManage,canAudit,transition,seed,type Role,type Project,type Request,type Attachment,type Document} from './workflow'
const key='audit-requirements-v2'
let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{}
const db=reactive(saved?.version===2?saved.data:seed()) as ReturnType<typeof seed>
watch(db,()=>localStorage.setItem(key,JSON.stringify({version:2,data:db})),{deep:true})
const role=ref<Role>('工程管理'), person=ref(manager), page=ref('统一工作台'), projectId=ref(db.projects[0]?.id||''), keyword=ref(''),typeFilter=ref('全部'), region=ref('全部'),month=ref('')
watch(role,v=>{person.value=v==='工程管理'?manager:v==='造价审计'?auditor:v==='超管'?'管理员':'查阅用户';page.value='统一工作台'})
const manage=computed(()=>canManage(role.value)),audit=computed(()=>canAudit(role.value))
const scope=computed(()=>db.projects.filter(p=>role.value==='超管'||role.value==='工程管理'&&p.manager===person.value||role.value==='造价审计'&&(p.auditor===person.value||db.requests.some(r=>r.projectId===p.id&&r.reviewer===person.value))))
const project=computed(()=>scope.value.find(p=>p.id===projectId.value));watch(scope,v=>{if(!v.some(p=>p.id===projectId.value))projectId.value=v[0]?.id||''})
const rows=computed(()=>scope.value.filter(p=>[p.id,p.name,p.company].join().includes(keyword.value)))
const requests=computed(()=>db.requests.filter(r=>!r.deleted&&r.projectId===projectId.value&&(role.value==='超管'||role.value==='工程管理'&&r.author===person.value||role.value==='造价审计'&&(r.auditor===person.value||r.reviewer===person.value))&&(typeFilter.value==='全部'||r.type===typeFilter.value)))
const pending=computed(()=>db.requests.filter(r=>!r.deleted&&scope.value.some(p=>p.id===r.projectId)&&(role.value==='工程管理'?r.author===person.value&&['已退回','已完成','已撤回'].includes(r.status):role.value==='造价审计'?(person.value===r.reviewer?r.status==='待复审':r.auditor===person.value&&['已上报','已签收','审核中','复审退回'].includes(r.status)):role.value==='超管'&&!['已完成','已撤回'].includes(r.status))))
const groups=computed(()=>[{name:'工作台',items:['统一工作台']},...(manage.value?[{name:'项目报送平台',items:['项目台账','资料报送']}]:[]),...(audit.value?[{name:'审计管理平台',items:['审计项目']}]:[]),{name:'招投标平台',items:['DeepSeek对话']},{name:'数据支撑平台',items:['信息价查询','网页询价','AI询价','造价指标','知识问答']},{name:'集团信息平台',items:['资料中心']},...(role.value==='超管'?[{name:'管理',items:['数据库']}]:[])])
const logs=ref<string[]>([]),detail=ref<Project>(),selected=ref<Request>(),docDetail=ref<Document>(),aiResult=ref(''),aiTitle=ref(''),chat=ref(''),messages=ref<{q:string,a:string}[]>([])
watch(page,()=>{keyword.value='';messages.value=[]})
const projectDialog=ref(false),editing=ref(''),form=reactive({name:'',company:'',sector:'协鑫科技',category:'新建',manager,auditor,status:'筹建',budget:0}),newFiles=ref<Attachment[]>([])
const attachmentDb='audit-demo-attachments'
function storeBlob(id:string,file:Blob){return new Promise<void>((resolve,reject)=>{const open=indexedDB.open(attachmentDb,1);open.onupgradeneeded=()=>open.result.createObjectStore('files');open.onerror=()=>reject(open.error);open.onsuccess=()=>{const d=open.result,t=d.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=()=>{d.close();resolve()};t.onerror=()=>{d.close();reject(t.error)}}})}
function getBlob(id:string){return new Promise<Blob|undefined>((resolve,reject)=>{const open=indexedDB.open(attachmentDb,1);open.onerror=()=>reject(open.error);open.onsuccess=()=>{const d=open.result;if(!d.objectStoreNames.contains('files')){d.close();resolve(undefined);return}const t=d.transaction('files'),q=t.objectStore('files').get(id);q.onsuccess=()=>{resolve(q.result);d.close()};q.onerror=()=>reject(q.error)}})}
async function files(event:Event,target:Attachment[],category='资料'){for(const file of Array.from((event.target as HTMLInputElement).files||[])){const id=crypto.randomUUID();try{await storeBlob(id,file);target.push({id,name:file.name,category,blobKey:id})}catch{ElMessage.error('附件保存失败，请重试')}}(event.target as HTMLInputElement).value=''}
async function download(f:Attachment){try{const blob=f.blobKey?await getBlob(f.blobKey):new Blob(['合成演示文件：'+f.name+'\n不作为正式审计资料。'],{type:'text/plain;charset=utf-8'});if(!blob){ElMessage.error('本地附件不存在，请重新选择原文件');return false}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true}catch{ElMessage.error('下载失败');return false}}
function openProject(p?:Project){if(!manage.value)return;editing.value=p?.id||'';Object.assign(form,p||{name:'',company:'',sector:'协鑫科技',category:'新建',manager,auditor,status:'筹建',budget:0});newFiles.value=p?[...p.files]:[];projectDialog.value=true}
function saveProject(){if(!manage.value||!form.name.trim()||!form.company.trim()||!form.manager.trim()||!form.auditor.trim()||!Number.isFinite(form.budget)||form.budget<0){ElMessage.warning('请完整填写项目、公司、负责人、造价对接人与有效预算');return}const p=db.projects.find(p=>p.id===editing.value);if(p){Object.assign(p,form);p.files=[...newFiles.value]}else{const id='XM-'+Date.now();db.projects.push({...form,id,archived:false,contracts:[],files:[...newFiles.value]});projectId.value=id}projectDialog.value=false;ElMessage.success('项目已加入台账')}
async function contract(){if(!manage.value||!project.value)return;try{const {value}=await ElMessageBox.prompt('填写合同名称，一个项目可有多个合同','新增合同',{inputValidator:v=>!!v?.trim()||'请填写合同名称'});project.value.contracts.push({id:'HT-'+Date.now(),name:value.trim()})}catch{}}
const reportDialog=ref(false),reportType=ref('进度款上报'),contractId=ref(''),reportFiles=ref<Attachment[]>([])
function submitReport(){if(!manage.value||!project.value)return;if(!contractId.value||!reportFiles.value.length){ElMessage.warning('请选择合同并上传本次资料');return}db.requests.push({id:'BS-'+Date.now(),projectId:project.value.id,contractId:contractId.value,type:reportType.value,status:'已上报',stage:'待审核',opinion:'',files:[...reportFiles.value],results:[],history:[`${new Date().toLocaleString()} ${person.value} 上报`],deleted:false,author:person.value,auditor:project.value.auditor,reviewer});reportDialog.value=false;ElMessage.success('已上报，已进入指定造价人员待办')}
async function act(r:Request,action:string){try{let note='';if(['退回','撤回','删除'].includes(action)){const res=await ElMessageBox.prompt(action==='删除'?'将逻辑删除并保留历史，填写理由':'填写意见或理由',action,{inputValidator:v=>!!v?.trim()||'必填理由'});note=res.value}if(action==='下载资料'){if(!audit.value||person.value!==r.auditor&&role.value!=='超管'||!['已签收','审核中','复审退回'].includes(r.status))throw new Error('请先由指定初审人签收');if(!r.files.length)throw new Error('没有可下载附件');for(const f of r.files)if(!await download(f))return}transition(r,action,role.value,person.value,note);ElMessage.success(action+'完成')}catch(e){if(e instanceof Error)ElMessage.warning(e.message)}}
async function manual(r:Request){try{const res=await ElMessageBox.prompt('输入状态与原因，以“；”分隔。允许：已上报、已签收、审核中、待复审、已完成、已退回、已撤回','手动调整状态',{inputValidator:v=>/^(已上报|已签收|审核中|待复审|已完成|已退回|已撤回)；.+/.test(v||'')||'请输入合法状态；原因'});if(role.value!=='超管'&&!(audit.value&&r.auditor===person.value))throw new Error('无权调整');const [s,...n]=res.value.split('；');if(s==='已完成'&&role.value!=='超管')throw new Error('最终完成须经复审');if(['待复审','已完成'].includes(s)&&!r.results.length)throw new Error('缺少成果，不能进入该状态');r.status=s;r.stage=['待复审','已完成'].includes(s)?'已审核':'待审核';r.history.push(`${person.value} 手动调整 ${s}：${n.join('；')}`)}catch(e){if(e instanceof Error)ElMessage.warning(e.message)}}
function preaudit(r:Request){aiTitle.value='DeepSeek AI预审（模拟）';aiResult.value=`报送 ${r.id}，${r.type}。\n资料 ${r.files.length} 份；合同：${project.value?.contracts.find(c=>c.id===r.contractId)?.name}。\n建议核实：付款累计金额、合同付款比例、签章完整性。\n当前仅模拟提示，未读取文件或调用模型，不构成审核结论。`}
function analyze(r:Request){if(!r.results.length){ElMessage.warning('先上传线下审核成果');return}aiTitle.value='成果AI分析与模板生成（模拟）';aiResult.value=`成果 ${r.results.map(f=>f.name).join('、')}\n将核对送审与审定口径，并生成审计报告和审定单。\n正式模板尚未提供，当前不冒充已生成正式报告。可下载演示草稿用于确认字段。\n项目：${project.value?.name}；类型：${r.type}；审核意见与金额待人工填写。`}
function notify(p:Project){projectId.value=p.id;page.value=manage.value?'资料报送':audit.value?'审计项目':'资料中心'}
const docDialog=ref(false),docEdit=ref(''),docForm=reactive({title:'',category:'制度',region:'集团',month:'2026-11',version:'V1.0',summary:'',published:true}),docFiles=ref<Attachment[]>([])
function editDoc(d?:Document){if(role.value!=='超管')return;docEdit.value=d?.id||'';Object.assign(docForm,d||{title:'',category:'制度',region:'集团',month:'2026-11',version:'V1.0',summary:'',published:true});docFiles.value=d?.file?[d.file]:[];docDialog.value=true}
function saveDoc(){if(role.value!=='超管'||!docForm.title.trim()||!docForm.summary.trim()){ElMessage.warning('请填写标题和内容摘要');return}const old=db.documents.find(d=>d.id===docEdit.value);if(old){logs.value.push(`${person.value} 更新 ${old.title} ${old.version}`);Object.assign(old,docForm,{file:docFiles.value[0]})}else db.documents.push({...docForm,id:crypto.randomUUID(),file:docFiles.value[0]});docDialog.value=false}
const documents=computed(()=>db.documents.filter(d=>(d.published||role.value==='超管')&&d.title.includes(keyword.value)))
const prices=computed(()=>db.documents.filter(d=>d.published&&d.category==='造价信息'&&(region.value==='全部'||d.region===region.value)&&(!month.value||d.month===month.value)))
async function ask(){if(!chat.value.trim())return;const q=chat.value;chat.value='';let a='';if(page.value==='知识问答'||page.value==='资料中心'){const institutional=/集团|制度|规定|办法|流程|报销/.test(q);const source=db.documents.find(d=>d.published&&d.category==='制度');a=institutional?(source?`分类：集团制度。\n依据《${source.title}》${source.version}：${source.summary}\n来源ID：${source.id}，可在资料中心查看。`:'分类：集团制度。当前知识库资料不足，不使用通用回答替代集团制度。'):'分类：通用知识。正式版由DeepSeek通用回答，不限定于集团知识库；当前为模拟响应，请提供具体问题供后续验证。'}else if(page.value==='AI询价')a=`针对“${q}”的模拟询价说明：需确认材料规格、数量、地区、税率、运费与时点。当前未联网，不提供虚构市场价格。正式版由DeepSeek归纳可追溯询价来源。`;else a=`DeepSeek招投标助手（模拟）：已收到“${q}”。可讨论招标条款、技术要求与报价澄清；当前未调用真实模型。`;messages.value.push({q,a})}
const sites=reactive([{name:'惠讯网',url:''},{name:'我的钢铁网',url:'https://www.mysteel.com'},{name:'材价助手',url:''},{name:'淘宝',url:'https://www.taobao.com'}]),siteUrl=ref(''),embed=ref(false),urlInput=ref(''),excelFiles=ref<Attachment[]>([])
function visit(url:string){try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))throw 0;siteUrl.value=u.href;embed.value=false}catch{ElMessage.warning('请填写完整的http或https网址；尚未确认的站点不预填猜测链接')}}
async function resultEdit(r:Request,remove=false){if(!audit.value||(person.value!==r.auditor&&role.value!=='超管'))return;try{const {value}=await ElMessageBox.prompt('说明撤回成果的原因；保留旧附件和操作轨迹','撤回成果',{inputValidator:v=>!!v?.trim()||'请填写原因'});r.history.push(`${person.value} 撤回成果：${value}，旧文件：${r.results.map(f=>f.name).join('、')}`);r.status='审核中';r.stage='待审核';if(remove){r.history.push('旧成果附件逻辑移出本次提交，原文件保留本地存储');r.results=[]}}catch{}}
const matching=computed(()=>db.requests.filter(r=>!r.deleted&&r.projectId===projectId.value))
</script>

<template>
<div class="demo-shell">
 <header><strong>智慧审计工作台</strong><el-select v-model="projectId" aria-label="当前项目" style="width:300px"><el-option v-for="p in scope" :key="p.id" :label="p.name" :value="p.id"/></el-select><span class="grow"/><el-select v-model="role" aria-label="当前角色" style="width:145px"><el-option v-for="r in roles" :key="r" :value="r"/></el-select><el-select v-if="role==='造价审计'" v-model="person" aria-label="审计人员" style="width:120px"><el-option :value="auditor" label="林岚·初审"/><el-option :value="reviewer" label="周宁·复审"/></el-select><span v-else>{{person}}</span></header>
 <div class="notice">需求校正演示 · 合成数据、本地保存 · 无真实后端、权限隔离或DeepSeek调用 · 不是最终产品</div>
 <aside><section v-for="g in groups" :key="g.name"><small>{{g.name}}</small><button v-for="i in g.items" :key="i" :class="{active:page===i}" @click="page=i">{{i}}<b v-if="i==='审计项目'"> {{pending.length}}</b></button></section></aside>
 <main><div class="heading"><div><small>{{role}} / {{project?.id||'未选择项目'}}</small><h1>{{page}}</h1></div><el-tag type="info">需求演示 V2</el-tag></div>
 <template v-if="page==='统一工作台'">
  <div class="cards"><article v-for="s in [{label:'跟踪项目',n:scope.length},{label:'已完成项目',n:scope.filter(p=>p.status==='已结束').length},{label:'待办项目',n:new Set(pending.map(r=>r.projectId)).size},{label:'已归档项目',n:scope.filter(p=>p.archived).length}]" :key="s.label"><span>{{s.label}}</span><strong>{{s.n}}</strong></article></div>
  <div class="panel"><h2>项目台账 · 按项目号跟进</h2><p>完成与归档分开统计；一个项目可含多个合同。待办按项目去重。</p><el-table :data="scope"><el-table-column prop="id" label="项目号" width="165"/><el-table-column prop="name" label="台账名称" min-width="230"/><el-table-column label="合同数" width="80"><template #default="{row}">{{row.contracts.length}}</template></el-table-column><el-table-column prop="status" label="项目状态"/><el-table-column label="待办" width="80"><template #default="{row}">{{pending.filter(r=>r.projectId===row.id).length}}</template></el-table-column><el-table-column label="归档"><template #default="{row}">{{row.archived?'已归档':'未归档'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="notify(row)">跟进</el-button></template></el-table-column></el-table></div>
 </template>
 <template v-else-if="page==='项目台账'">
  <div class="toolbar"><el-input v-model="keyword" placeholder="项目号、名称、公司" clearable style="width:300px"/><el-button type="primary" @click="openProject()">新建项目</el-button></div>
  <el-table :data="rows"><el-table-column prop="id" label="项目号" min-width="165"/><el-table-column prop="name" label="项目名称" min-width="230"/><el-table-column prop="company" label="项目公司"/><el-table-column prop="sector" label="所属板块"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="200"><template #default="{row}"><el-button link @click="detail=row">概况/附件</el-button><el-button link type="primary" @click="openProject(row)">修改</el-button><el-button link @click="row.archived=!row.archived">{{row.archived?'取消归档':'归档'}}</el-button></template></el-table-column></el-table>
 </template>
 <template v-else-if="page==='资料报送'||page==='审计项目'">
  <div class="panel"><div class="toolbar"><h2>{{project?.name||'请选择项目'}}</h2><el-button v-if="manage" @click="contract">新增合同</el-button><el-button v-if="page==='资料报送'&&project" type="primary" @click="reportFiles=[];contractId=project.contracts[0]?.id||'';reportDialog=true">本次资料上报</el-button></div><p>以合同及每次报送作为审核单元，项目阶段不覆盖其他合同的审核状态。</p><el-tag v-for="c in project?.contracts" :key="c.id" style="margin:4px">{{c.id}} · {{c.name}}</el-tag><el-empty v-if="!project?.contracts.length" description="先新增合同，再进行报送"/></div>
  <div class="toolbar"><el-radio-group v-model="typeFilter"><el-radio-button value="全部">全部</el-radio-button><el-radio-button value="进度款上报">进度款上报</el-radio-button><el-radio-button value="结算上报">结算上报</el-radio-button></el-radio-group></div>
  <el-table :data="requests"><el-table-column prop="id" label="报送编号" min-width="145"/><el-table-column prop="contractId" label="合同"/><el-table-column prop="type" label="报送类型"/><el-table-column label="状态"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><el-table-column prop="stage" label="当前审核阶段"/><el-table-column prop="opinion" label="回复意见"/><el-table-column label="操作" width="270"><template #default="{row}"><el-button link type="primary" @click="selected=row">资料与办理</el-button><el-button v-if="audit&&row.status==='已上报'" link @click="act(row,'签收')">签收</el-button><el-button v-if="audit&&['已上报','待复审'].includes(row.status)" link type="danger" @click="act(row,'退回')">退回</el-button></template></el-table-column></el-table>
 </template>
 <template v-else-if="page==='数据库'"><el-alert title="仅超管可见：数据库概览演示；不是直连数据库或任意SQL控制台" :closable="false"/><div class="cards"><article><span>项目</span><strong>{{db.projects.length}}</strong></article><article><span>合同</span><strong>{{db.projects.reduce((n,p)=>n+p.contracts.length,0)}}</strong></article><article><span>报送记录（含删除历史）</span><strong>{{db.requests.length}}</strong></article><article><span>集团资料</span><strong>{{db.documents.length}}</strong></article></div><pre>{{JSON.stringify({projects:db.projects,requests:db.requests},null,2)}}</pre></template>
 <template v-else-if="page==='资料中心'">
  <div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索合同、制度、造价信息、汇编" style="width:350px"/><el-button v-if="role==='超管'" type="primary" @click="editDoc()">发布资料</el-button><el-button @click="page='知识问答'">制度问答</el-button></div><el-table :data="documents"><el-table-column prop="title" label="资料名称" min-width="280"/><el-table-column prop="category" label="分类"/><el-table-column prop="region" label="地区"/><el-table-column prop="version" label="版本"/><el-table-column prop="month" label="月份"/><el-table-column label="状态"><template #default="{row}">{{row.published?'已发布':'已撤回'}}</template></el-table-column><el-table-column label="操作" width="260"><template #default="{row}"><el-button link @click="docDetail=row">预览/详情</el-button><el-button link @click="download(row.file||{id:row.id,name:row.title+'.txt',category:row.category})">下载</el-button><template v-if="role==='超管'"><el-button link @click="editDoc(row)">更新</el-button><el-button link @click="row.published=!row.published">{{row.published?'撤回':'发布'}}</el-button></template></template></el-table-column></el-table>
 </template>
 <template v-else-if="page==='信息价查询'"><div class="toolbar"><el-select v-model="region" style="width:160px"><el-option value="全部"/><el-option v-for="r in [...new Set(db.documents.filter(d=>d.category==='造价信息').map(d=>d.region))]" :key="r" :value="r"/></el-select><el-input v-model="month" type="month" style="width:180px"/><el-button @click="month='';region='全部'">重置</el-button></div><el-alert title="信息价为合成示例，正式数据由超管维护；按地区、月份和税费口径使用" :closable="false"/><el-table :data="prices"><el-table-column prop="title" label="信息价资料"/><el-table-column prop="region" label="地区"/><el-table-column prop="month" label="月份"/><el-table-column label="查看"><template #default="{row}"><el-button link @click="docDetail=row">详情与价格口径</el-button></template></el-table-column></el-table></template>
 <template v-else-if="page==='网页询价'"><div class="panel"><h2>网页询价工作区</h2><p>站点可禁止嵌入或要求登录。优先在新窗口使用原站，不代理登录或绕过限制。惠讯网、材价助手的准确网址待确认。</p><div class="toolbar"><el-button v-for="s in sites" :key="s.name" @click="s.url?visit(s.url):ElMessage.info('请在下方填写该站准确网址')">{{s.name}}</el-button></div><div class="toolbar"><el-input v-model="urlInput" placeholder="输入已确认的完整网址"/><el-button @click="visit(urlInput)">打开工作区</el-button></div><template v-if="siteUrl"><a :href="siteUrl" target="_blank" rel="noopener noreferrer">新窗口访问 {{siteUrl}}</a><el-button @click="embed=!embed">{{embed?'关闭嵌入':'尝试嵌入'}}</el-button><iframe v-if="embed" :src="siteUrl" title="外部询价网站" sandbox="allow-forms allow-scripts allow-same-origin allow-popups" referrerpolicy="no-referrer"/></template></div></template>
 <template v-else-if="page==='造价指标'"><el-alert title="仅纳入已完成且审计通过的项目；当前尚无真实模型分析" :closable="false"/><el-table :data="db.projects.filter(p=>p.status==='已结束')"><el-table-column prop="name" label="已完成项目"/><el-table-column prop="category" label="工程类别"/><el-table-column prop="budget" label="项目预算（非审定金额）"/><el-table-column label="分析"><template #default="{row}"><el-button @click="aiTitle='造价指标（模拟）';aiResult=row.name+'：缺少经复审的审定金额、建筑面积和专业拆分，暂不能形成可用指标。不能把预算除以未知面积生成指标。'">AI分析</el-button></template></el-table-column></el-table></template>
 <template v-else-if="['DeepSeek对话','AI询价','知识问答'].includes(page)"><div class="panel"><h2>{{page==='DeepSeek对话'?'DeepSeek · 招投标助手':page}}</h2><p>{{page==='知识问答'?'先分类：集团制度调用已发布知识库，其他问题走通用问答。本轮采用规则分类模拟。':'演示响应，不连接外部模型或生成无来源报价。'}}</p><template v-if="page==='AI询价'"><label class="upload">上传Excel材料表<input type="file" accept=".xlsx,.xls" @change="files($event,excelFiles,'材料表')"/></label><p v-for="f in excelFiles" :key="f.id">{{f.name}} · 已保存；演示暂不解析Excel内容，正式版需后端解析与询价。</p></template><article v-for="(m,i) in messages" :key="i" class="bubble"><strong>{{m.q}}</strong><pre>{{m.a}}</pre><el-button v-if="page==='知识问答'&&/来源ID/.test(m.a)" link @click="docDetail=db.documents.find(d=>d.published&&m.a.includes(d.id))">打开制度来源</el-button></article><el-input v-model="chat" type="textarea" :rows="4" placeholder="输入问题或材料名称、规格、地区、月份"/><el-button type="primary" style="margin-top:12px" @click="ask">发送</el-button></div></template>
 </main>
 <el-dialog v-model="projectDialog" :title="editing?'修改项目':'新建项目'" width="720px"><el-form label-width="110px"><el-form-item v-for="f in [{key:'name',label:'项目名称'},{key:'company',label:'项目公司'},{key:'manager',label:'项目负责人'},{key:'auditor',label:'造价对接人'}]" :key="f.key" :label="f.label" required><el-input v-model="(form as any)[f.key]"/></el-form-item><el-form-item label="所属板块"><el-select v-model="form.sector"><el-option v-for="x in ['协鑫科技','协鑫集成','协鑫能科']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="工程类别"><el-select v-model="form.category"><el-option v-for="x in ['新建','改建','扩建','检维修','技改']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="项目状态"><el-select v-model="form.status"><el-option v-for="x in ['筹建','在建','竣工','停建','已结束']" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="项目预算（元）"><el-input-number v-model="form.budget" :min="0" :precision="2" :max="999999999999"/></el-form-item><el-form-item label="项目文件夹"><input type="file" multiple @change="files($event,newFiles,'项目资料')"/></el-form-item><p v-for="f in newFiles" :key="f.id">{{f.category}} / {{f.name}}</p></el-form><template #footer><el-button @click="projectDialog=false">取消</el-button><el-button type="primary" @click="saveProject">保存到台账</el-button></template></el-dialog>
 <el-drawer :model-value="!!detail" @close="detail=undefined" title="项目概况与分类归档" size="55%"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item v-for="(v,k) in {项目号:detail.id,项目名称:detail.name,项目公司:detail.company,所属板块:detail.sector,工程类别:detail.category,负责人:detail.manager,造价对接人:detail.auditor,状态:detail.status,预算:detail.budget}" :key="k" :label="k">{{v}}</el-descriptions-item></el-descriptions><h3>附件</h3><p v-for="f in detail.files" :key="f.id">{{f.category}} / {{f.name}} <el-button link @click="download(f)">下载</el-button></p><el-empty v-if="!detail.files.length" description="暂无附件"/></template></el-drawer>
 <el-dialog v-model="reportDialog" title="本次资料上报" width="600px"><el-form label-width="90px"><el-form-item label="合同"><el-select v-model="contractId"><el-option v-for="c in project?.contracts" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="上报类型"><el-radio-group v-model="reportType"><el-radio value="进度款上报">进度款上报</el-radio><el-radio value="结算上报">结算上报</el-radio></el-radio-group></el-form-item><el-form-item label="本次资料"><input type="file" multiple @change="files($event,reportFiles,reportType)"/></el-form-item><p v-for="f in reportFiles" :key="f.id">{{f.name}}</p><p>接收初审：{{project?.auditor}}；复审：{{reviewer}}（演示固定，可在正式需求中配置）</p></el-form><template #footer><el-button type="primary" @click="submitReport">提交上报</el-button></template></el-dialog>
 <el-drawer :model-value="!!selected" @close="selected=undefined" title="报送审核与成果反馈" size="65%"><template v-if="selected"><h2>{{selected.id}} · {{selected.type}}</h2><p>{{selected.contractId}} / {{selected.status}} / {{selected.stage}}</p><div class="toolbar"><template v-if="audit"><el-button v-if="selected.status==='已上报'" @click="act(selected,'签收')">签收</el-button><el-button v-if="['已上报','待复审'].includes(selected.status)" @click="act(selected,'退回')">退回（必填理由）</el-button><el-button @click="preaudit(selected)">AI预审</el-button><el-button v-if="['已签收','审核中','复审退回'].includes(selected.status)" @click="act(selected,'下载资料')">下载资料并开始审核</el-button><el-button v-if="selected.status==='待复审'&&(person===selected.reviewer||role==='超管')" type="primary" @click="act(selected,'复审通过')">复审通过并反馈工程管理</el-button><el-button @click="manual(selected)">手动调整状态</el-button></template><template v-if="manage"><el-button @click="act(selected,'撤回')">撤回</el-button><el-button type="danger" @click="act(selected,'删除');selected=undefined">删除（保留历史）</el-button></template></div><h3>报送资料</h3><p v-for="f in selected.files" :key="f.id">{{f.name}} <el-button v-if="!audit||!['已上报'].includes(selected.status)" link @click="audit?act(selected,'下载资料'):download(f)">下载</el-button></p><template v-if="manage&&['已撤回','已退回'].includes(selected.status)"><p>修改补充资料（保留原附件和历史）</p><input type="file" multiple @change="files($event,selected!.files,'补充资料')"/><el-button @click="act(selected,'重新上报')">修改后重新上报</el-button></template><h3>线下审核成果</h3><div v-if="audit&&(person===selected.auditor||role==='超管')&&selected.results.length" class="toolbar"><el-button @click="resultEdit(selected)">撤回成果并修改</el-button><el-button @click="resultEdit(selected,true)">删除本次成果（保留轨迹）</el-button></div><template v-if="audit&&['审核中','复审退回'].includes(selected.status)&&(person===selected.auditor||role==='超管')"><input type="file" multiple @change="files($event,selected!.results,'审计成果')"/><div class="toolbar"><el-button @click="analyze(selected)">AI分析 / 审计报告与审定单</el-button><el-button type="primary" @click="act(selected,'提交成果')">提交下一级复审</el-button></div></template><p v-for="f in selected.results" :key="f.id">{{f.name}} <el-button link @click="download(f)">下载成果</el-button></p><el-alert v-if="selected.status==='已完成'" title="复审完成，工程管理人员已收到最终成果" :closable="false" type="success"/><h3>回复意见与历史</h3><el-input :model-value="selected.opinion" readonly type="textarea"/><p v-for="(h,i) in selected.history" :key="i">{{h}}</p></template></el-drawer>
 <el-dialog :model-value="!!aiResult" @close="aiResult=''" :title="aiTitle" width="700px"><pre>{{aiResult}}</pre><el-button v-if="aiTitle.includes('模板')" @click="download({id:'draft',name:'审计成果字段演示草稿.txt',category:'演示'})">下载字段演示草稿</el-button></el-dialog>
 <el-dialog v-model="docDialog" title="超管维护集团资料" width="650px"><el-form label-width="90px"><el-form-item v-for="f in [{key:'title',label:'标题'},{key:'region',label:'地区'},{key:'month',label:'月份'},{key:'version',label:'版本'}]" :key="f.key" :label="f.label"><el-input v-model="(docForm as any)[f.key]"/></el-form-item><el-form-item label="分类"><el-select v-model="docForm.category"><el-option v-for="c in ['合同','制度','造价信息','汇编']" :key="c" :value="c"/></el-select></el-form-item><el-form-item label="预览内容"><el-input v-model="docForm.summary" type="textarea" :rows="5"/></el-form-item><el-form-item label="附件"><input type="file" @change="docFiles=[];files($event,docFiles,'集团资料')"/></el-form-item><p v-for="f in docFiles" :key="f.id">{{f.name}}</p></el-form><template #footer><el-button type="primary" @click="saveDoc">保存并发布</el-button></template></el-dialog>
 <el-dialog :model-value="!!docDetail" @close="docDetail=undefined" title="资料详情与内容预览" width="700px"><template v-if="docDetail"><h2>{{docDetail.title}}</h2><p>{{docDetail.category}} / {{docDetail.region}} / {{docDetail.month}} / {{docDetail.version}}</p><el-tag>{{docDetail.published?'已发布':'已撤回'}}</el-tag><pre>{{docDetail.summary}}</pre><p>当前预览为超管维护的内容摘要；原附件请下载。正式版增加PDF原件预览。</p><el-button @click="download(docDetail.file||{id:docDetail.id,name:docDetail.title+'.txt',category:docDetail.category})">下载资料</el-button><el-button v-if="docDetail.category==='制度'" @click="page='知识问答';docDetail=undefined">制度问答</el-button></template></el-dialog>
</div>
</template>

<style>
*{box-sizing:border-box}body{margin:0;font-family:'Microsoft YaHei',sans-serif;background:#f3f6fa;color:#24364a}.demo-shell header{height:72px;display:flex;align-items:center;gap:20px;background:white;border-bottom:1px solid #e2e8f0;padding:0 28px;position:fixed;top:0;left:0;right:0;z-index:20}.demo-shell header strong{font-size:21px;color:#173d68}.grow{flex:1}.notice{position:fixed;top:72px;left:0;right:0;background:#eaf2fb;color:#4b6581;font-size:12px;padding:8px 28px;z-index:19}.demo-shell aside{position:fixed;top:104px;bottom:0;width:220px;background:white;overflow:auto;padding:16px}.demo-shell aside small{display:block;color:#8796a7;padding:15px 10px 7px}.demo-shell aside button{display:block;border:0;background:none;padding:12px;text-align:left;width:100%;border-radius:6px;color:#40546b;cursor:pointer}.demo-shell aside button:hover,.demo-shell aside button.active{background:#eaf2ff;color:#2065b3}.demo-shell main{margin:104px 0 0 220px;padding:30px;min-height:calc(100vh - 104px)}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}h1{font-size:26px;margin:8px 0}h2{font-size:18px}small{color:#7b8a9b}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-bottom:24px}.cards article,.panel{background:white;border:1px solid #e4eaf2;border-radius:10px;padding:24px}.cards span{display:block;color:#6d7f94}.cards strong{display:block;font-size:34px;margin-top:12px;color:#22588b}.panel{margin-bottom:20px}.panel p{color:#728196;font-size:13px}.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.toolbar h2{margin-right:auto}.bubble{padding:18px;background:#f4f7fb;margin:15px 0;border-radius:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;line-height:1.8;background:#f7f9fc;padding:16px;border-radius:8px;max-height:500px;overflow:auto}iframe{width:100%;height:600px;border:1px solid #dce4ee;margin-top:20px}.upload{display:block;margin:18px 0}.el-table{border-radius:8px}.el-drawer p{line-height:1.8}@media(max-width:1400px){.demo-shell main{padding:22px}.cards{gap:12px}.cards article{padding:18px}.demo-shell aside{width:190px}.demo-shell main{margin-left:190px}}
</style>
